{"ok": true, "result": {"path": "dbt/models/staging/stg_bureau.sql", "content": "with source as (
    select *
    from {{ source('raw', 'bureau') }}
    where {{ partition_predicate('_ds') }}
      and {{ not_quarantined('_ds', 'raw.bureau') }}
),

ranked as (
    select
        *,
        row_number() over (partition by _ds, borrower_id order by _row desc) as rn
    from source
)

select
    _ds as ds,
    borrower_id,
    score,
    score_date
from ranked
where rn = 1
"}}

{"ok": true, "result": {"path": "dbt/macros/partitions.sql", "content": "{#- Partition helpers. Every incremental model is partitioned by `ds` (a business day). -#}

{% macro partition_predicate(column) -%}
  {%- if var('ds', none) is not none -%}
    {{ column }} = cast('{{ var("ds") }}' as date)
  {%- else -%}
    true
  {%- endif -%}
{%- endmacro %}

{% macro delete_partition() -%}
  {%- if is_incremental() and var('ds', none) is not none -%}
    delete from {{ this }} where ds = cast('{{ var("ds") }}' as date)
  {%- else -%}
    select 1
  {%- endif -%}
{%- endmacro %}

{% macro not_quarantined(column, source_table) -%}
  {{ column }} not in (
    select ds from {{ source('ops', 'quarantine') }} where source_table = '{{ source_table }}'
  )
{%- endmacro %}
"}}

